const entradas = $input.all();
const grupos = new Map();

for (let indice = 0; indice < entradas.length; indice++) {
  const contexto =
    $('03 | Separar Dependências').itemMatching(indice).json;

  const dependencia = contexto.dependencia;

  if (
    !dependencia ||
    !dependencia.ecossistema ||
    !dependencia.nome ||
    !dependencia.versao
  ) {
    throw new Error('Contexto da dependência incompleto.');
  }

    const chave = JSON.stringify([
    contexto.meta?.tenant_id,
    contexto.meta?.id_evento,
    dependencia.ecossistema,
    dependencia.nome,
    dependencia.versao,
  ]);

  if (!grupos.has(chave)) {
    grupos.set(chave, {
      contexto,
      indices: [],
      paginasValidas: 0,
      ultimaPaginaTemProxima: false,
      erros: [],
      avisos: new Map(),
    });
  }

    const grupo = grupos.get(chave);
  grupo.indices.push(indice);

  const resposta = entradas[indice].json;
  let corpo = resposta.body;

  if (typeof corpo === 'string') {
    try {
      corpo = JSON.parse(corpo);
    } catch {
      corpo = null;
    }
  }

  if (
    resposta.error ||
    resposta.statusCode !== 200 ||
    !corpo ||
    typeof corpo !== 'object' ||
    Array.isArray(corpo) ||
    (corpo.vulns !== undefined && !Array.isArray(corpo.vulns)) ||
    (corpo.next_page_token !== undefined &&
      typeof corpo.next_page_token !== 'string')
  ) {
    grupo.erros.push(
      resposta.statusCode
        ? `Consulta não concluída: HTTP ${resposta.statusCode}.`
        : 'Consulta não concluída: falha de conexão ou resposta inválida.'
    );
    continue;
  }

    grupo.paginasValidas++;
  grupo.ultimaPaginaTemProxima = Boolean(corpo.next_page_token);

  for (const aviso of corpo.vulns ?? []) {
    if (!aviso || typeof aviso.id !== 'string' || !aviso.id) {
      grupo.erros.push('O OSV retornou um aviso sem identificador válido.');
      continue;
    }

    if (aviso.withdrawn) continue;

    const aliases = Array.isArray(aviso.aliases)
      ? aviso.aliases
      : [];

    const cves = [...new Set(
      [aviso.id, ...aliases].filter(
        valor =>
          typeof valor === 'string' &&
          /^CVE-\d{4}-\d+$/i.test(valor)
      ).map(valor => valor.toUpperCase())
    )];

    const afetados = Array.isArray(aviso.affected)
      ? aviso.affected.filter(
          item =>
            item.package?.name === dependencia.nome &&
            item.package?.ecosystem === dependencia.ecossistema
        )
      : [];

     const severidades = [
      aviso.database_specific?.severity,
      ...afetados.map(item => item.ecosystem_specific?.severity),
    ].filter(
      valor => typeof valor === 'string' && valor.trim()
    );

    const cvss = [
      ...(Array.isArray(aviso.severity) ? aviso.severity : []),
      ...afetados.flatMap(
        item => Array.isArray(item.severity) ? item.severity : []
      ),
    ];

    grupo.avisos.set(aviso.id, {
      id: aviso.id,
      resumo: typeof aviso.summary === 'string' ? aviso.summary : '',
      cves,
      severidades_informadas: [...new Set(severidades)],
      cvss,
      url: `https://osv.dev/vulnerability/${encodeURIComponent(aviso.id)}`,
    });
  }
}

return [...grupos.values()].map(grupo => {
  const completa =
    grupo.paginasValidas > 0 &&
    grupo.erros.length === 0 &&
    !grupo.ultimaPaginaTemProxima;

  const avisos = [...grupo.avisos.values()];

  const cves = [...new Set(
    avisos.flatMap(aviso => aviso.cves)
  )].sort();

  const status = completa
    ? 'concluida'
    : grupo.paginasValidas > 0
      ? 'incompleta'
      : 'falha';

  return {
    json: {
      ...grupo.contexto,
      enriquecimento_osv: {
        status,
        consultado_em: new Date().toISOString(),
        paginas_validas: grupo.paginasValidas,
        paginacao_pendente: grupo.ultimaPaginaTemProxima,
        total_avisos: completa ? avisos.length : null,
        total_cves: completa ? cves.length : null,
        avisos_observados: avisos.length,
        cves_observados: cves,
        avisos,
        erros: grupo.erros,
      },
    },
    pairedItem: grupo.indices.map(item => ({ item })),
  };
});

const evento = $json;
const dependencia = evento.dependencia;
const consulta = evento.enriquecimento_osv;

if (!dependencia || !consulta) {
  throw new Error('Dependência ou resultado OSV ausente.');
}

const avisos = consulta.avisos ?? [];

const rotulos = {
  CRITICAL: 'crítica',
  HIGH: 'alta',
  MEDIUM: 'média',
  MODERATE: 'média',
  LOW: 'baixa',
};

const severidades = [...new Set(
  avisos
    .flatMap(aviso => aviso.severidades_informadas ?? [])
    .map(valor => rotulos[String(valor).trim().toUpperCase()])
    .filter(Boolean)
)];

let resultado;

if (consulta.status === 'concluida') {
  resultado = consulta.total_avisos === 0
    ? 'Nenhum aviso conhecido encontrado no OSV para a versão consultada.'
    : `${consulta.total_avisos} avisos OSV encontrados, com ` +
      `${consulta.total_cves} CVEs distintas identificadas.`;
} else if (consulta.status === 'incompleta') {
  resultado =
    'Consulta incompleta. Os resultados são parciais: ' +
    `${consulta.avisos_observados} avisos OSV observados.`;
} else {
  resultado =
    'Não foi possível concluir a consulta ao OSV. ' +
    'A ausência de resultados não indica ausência de vulnerabilidades.';
}

const cves = consulta.cves_observados ?? [];

const detalhes = [resultado];

if (cves.length > 0) {
  detalhes.push(`CVEs: ${cves.slice(0, 10).join(', ')}`);

  if (cves.length > 10) {
    detalhes.push(`Mais ${cves.length - 10} CVEs na saída do workflow.`);
  }
}

if (avisos.length > 0) {
  detalhes.push(
    severidades.length > 0
      ? `Severidades textuais informadas pelas fontes: ${severidades.join(', ')}.`
      : 'Classificação textual de severidade não informada nas fontes consultadas.'
  );
}

const risco = evento.risco?.nivel;

if (typeof risco === 'string' && risco.trim()) {
  detalhes.push(`Risco definido pelo núcleo: ${risco}.`);
}

const repositorio = evento.repositorio?.full_name;
const numeroPr = evento.pr?.numero;

const identificacao =
  `${repositorio} #${numeroPr}`;

const pacote =
  `${dependencia.nome} @ ${dependencia.versao}\n` +
  `Ecossistema: ${dependencia.ecossistema}`;

const slack_payload = {
  text: `Dependência nova: ${pacote}\n${identificacao}\n${resultado}`,
  blocks: [
    {
      type: 'section',
      text: {
        type: 'plain_text',
        text: `Dependência nova no PR\n${identificacao}`,
      },
    },
    {
      type: 'section',
      text: {
        type: 'plain_text',
        text: pacote,
      },
    },
    {
      type: 'section',
      text: {
        type: 'plain_text',
        text: detalhes.join('\n\n').slice(0, 2800),
      },
    },
  ],
};

return {
  json: {
    ...evento,
    texto_alerta: detalhes.join('\n\n'),
    slack_payload,
  },
};

const grupos = new Map();
for (let indice = 0; indice < $input.all().length; indice++) {
  const evento = $input.all()[indice].json;
  const identidade = [evento.meta?.tenant_id, evento.meta?.execution_id, evento.repositorio?.full_name, evento.pr?.numero];
  if (!Number.isSafeInteger(identidade[0]) || identidade[0] <= 0 ||
      typeof identidade[1] !== 'string' || !identidade[1] ||
      typeof identidade[2] !== 'string' || !identidade[2] ||
      !Number.isSafeInteger(identidade[3]) || identidade[3] <= 0) {
    throw new Error('Contexto OSV sem identificação completa da análise.');
  }
  const chave = JSON.stringify(identidade);
  if (!grupos.has(chave)) grupos.set(chave, { evento, identidade, indices: [], dependencias: new Map() });
  const grupo = grupos.get(chave);
  grupo.indices.push(indice);
  const dep = evento.dependencia;
  const resultado = evento.enriquecimento_osv;
  if (!dep || !resultado) throw new Error('Resultado OSV por dependência ausente.');
  grupo.dependencias.set(JSON.stringify([dep.ecossistema, dep.nome, dep.versao]), {
    ecossistema: dep.ecossistema, nome: dep.nome, versao: dep.versao,
    status: resultado.status, consultado_em: resultado.consultado_em,
    resumo: String(evento.texto_alerta || '').replace(/\n\nRisco definido pelo núcleo:[^\n]*/g, '').slice(0, 1500),
  });
}
return [...grupos.entries()].map(([chave, grupo]) => {
  const todas = [...grupo.dependencias.values()];
  const snapshot = {
    versao: 1, identidade: grupo.identidade, sha: grupo.evento.pr?.sha || '',
    consultado_em: todas.map(d => d.consultado_em).filter(Boolean).sort().at(-1) || new Date().toISOString(),
    total_dependencias: Math.max(todas.length, Number(grupo.evento.osv_pacotes_total) || 0), dependencias: todas.slice(0, 50),
    status: todas.every(d => d.status === 'falha') ? 'falha' :
      todas.length <= 50 && todas.length >= (Number(grupo.evento.osv_pacotes_total) || 0) && todas.every(d => d.status === 'concluida') ? 'concluida' : 'incompleta',
  };
  return { json: { ...grupo.evento, chave_osv: chave, contexto_osv_snapshot: snapshot,
    contexto_osv_serializado: JSON.stringify(snapshot) },
    pairedItem: grupo.indices.map(item => ({ item })) };
});
